test("redate claim scenario 1", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-04-05");
  expect(await ui.setRole(pg_uma, "wes", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "terms", "30");
  await ui.setSetting(pg_uma, "late-pct", "5.00");
  await ui.setSetting(pg_uma, "terms-B", "3");
  await ui.setSetting(pg_uma, "perm-void", "steward");
  await ui.setSetting(pg_uma, "grace-days", "0");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "33.33"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "33.33"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00", "from": "2026-03-01", "to": "2026-03-12"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P2", "from": "2026-03-16", "to": "2026-03-31"})).toBe(true);
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "A"}));
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "B"}));
  expect(await ui.retire(pg_uma, p_ada, "2026-03-01")).toBe(true);
  await ui.showRetired(pg_uma, true);
  expect(await ui.hold(pg_uma, p_ada, {"from": "2026-02-10"})).toBe(true);
  expect(await ui.addPatron(pg_uma, p_ben, "Ada")).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "10.00", "from": "2026-03-16"})).toBe(true);
  expect(await ui.editPerson(pg_uma, p_ada, {"terms": "3"})).toBe(true);
  const pg_wes = await ui.userPage(browser, "wes", sheet);
  expect(await ui.delegate(pg_wes, {"user": "vic", "from": "2026-02-10", "to": "2026-03-09"})).toBe(true);
  const pg_vic = await ui.userPage(browser, "vic", sheet);
  expect(await ui.periodAction(pg_vic, "P2", "close")).toBe(true);
  await ui.refresh(pg_vic);
  await expect(pg_vic.getByTestId("person-row-" + p_ada)).toHaveCount(0);
  expect(await ui.pasteClaims(pg_vic, "Ben,20.00,2026-03-01,a, b\nBen,12.50,,a, b")).toBe(2);
  const c_ben_0 = await ui.claimAt(pg_vic, p_ben, 0);
  const c_ben_1 = await ui.claimAt(pg_vic, p_ben, 1);
  expect(await ui.retire(pg_vic, p_ben, "2026-03-15")).toBe(true);
  await ui.showRetired(pg_vic, true);
  await ui.refresh(pg_wes);
  await ui.showRetired(pg_wes, true);
  expect(await ui.bulkOpen(pg_wes, [c_ben_1, c_ben_0])).toEqual({ opened: 2, refused: 0 });
  await ui.refresh(pg_uma);
  expect(await ui.bulkSettle(pg_uma, [c_ben_1, c_ben_0])).toEqual({ settled: 2, refused: 0 });
  expect(await ui.setSettingDated(pg_uma, "late-pct", "5.00", "2026-03-20", "5.00")).toBe(true);
  expect(await ui.addClaim(pg_uma, p_ada, {"amount": "4.00"})).toBeNull();
  await ui.refresh(pg_uma);
  expect(await ui.periodAction(pg_uma, "P1", "close")).toBe(true);
  expect(await ui.addClaim(pg_uma, p_ada, {"amount": "3.33"})).toBeNull();
  await ui.setToday(pg_uma, "2026-05-06");
  const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "7.77", "date": "2026-02-25"}));
  expect(await ui.addClaim(pg_uma, p_ben, {"amount": "25.00"})).toBeNull();
  await ui.refresh(pg_wes);
  expect(await ui.archive(pg_wes)).toBe(true);
  expect(await ui.addClaim(pg_wes, p_ben, {"amount": "20.00"})).toBeNull();
  await ui.refresh(pg_wes);
  await ui.expectAudit(sheet, [
    `ROLE_SET sheet=${sheet} by=uma user=wes role=steward`,
    `SETTING_CHANGED sheet=${sheet} by=uma key=terms value=30`,
    `SETTING_CHANGED sheet=${sheet} by=uma key=late-pct value=5.00`,
