                + " amount=" + claim.amount().toPlainString() + " date=" + claim.date()
                + (claim.number() == null ? "" : " number=" + claim.number()) + " old=" + redating.old() + " new="
                + redating.date());
        rollup.record(claim.sheetId(), redating.by(), before);
    }
}
